package it.frociart.app;
import java.util.*;
/** One read-only real runtime frame, bounded previews/pages and no evaluated expressions. */
final class FlowVariableInspection {
 static final int PAGE_SIZE=64,PREVIEW_LIMIT=160;
 static final class Row {
  final long frameId;final String name,type,role,preview;final int kind,group;final boolean parameter,result;final FlowEngine.Value value,previousValue;final int change;String changeName(){return change==1?"Nuova":change==2?"Modificata":"";}String displayPreview(){return change==0?preview:changeName()+" · "+preview;}
  boolean isVector(){return value.isVector();}int count(){return isVector()?value.vectorSize():0;}
  Row(FlowEngine.CallFrameSnapshot frame,String name,FlowEngine.Value value){this(frame,name,value,null,false);}
  Row(FlowEngine.CallFrameSnapshot frame,String name,FlowEngine.Value value,Row previous,boolean compared){change=compared?(previous==null?1:!previous.type.equals(frame.variableTypes.get(name))||!same(previous.value,value)?2:0):0;previousValue=previous==null?null:previous.value;frameId=frame.frameId;this.name=name;this.value=value;type=frame.variableTypes.get(name);boolean found=false;for(String p:frame.parameterNames)if(p.equalsIgnoreCase(name))found=true;parameter=found;result=frame.resultName!=null&&!frame.resultName.isEmpty()&&frame.resultName.equalsIgnoreCase(name);group=parameter?0:result?2:1;role=parameter?(result?"Parametro · risultato":"Parametro"):result?"Risultato":"Variabile locale";kind=type.startsWith("Intero")?1:type.startsWith("Reale")?2:type.startsWith("Testo")?3:type.startsWith("Logico")?4:0;preview=isVector()?"Vettore · "+count()+" elementi":compact(value.format());}
  String fullValue(){return value.format();}String elementValue(int index){if(!isVector())throw new IllegalStateException("La variabile non è un vettore.");return value.element(index).format();}
  Page<Element> elements(int offset){if(!isVector())throw new IllegalStateException("La variabile non è un vettore.");int start=pageStart(offset,count());List<Element> rows=new ArrayList<>();for(int i=start;i<Math.min(count(),start+PAGE_SIZE);i++)rows.add(new Element(i,value.element(i)));return new Page<>(rows,start,count());}
 }
 static final class Element {final int index;final FlowEngine.Value value;final String preview;Element(int index,FlowEngine.Value value){this.index=index;this.value=value;preview=compact(value.isNumber()?comparisonCell(value):value.format());}String fullValue(){return value.format();}}
 static final class Page<T> {final List<T> rows;final int offset,total;Page(List<T> rows,int offset,int total){this.rows=Collections.unmodifiableList(new ArrayList<>(rows));this.offset=offset;this.total=total;}boolean previous(){return offset>0;}boolean next(){return offset+rows.size()<total;}}
 final long generation;final int comparisonStep;final int steps;final FlowEngine.State state;final List<FlowEngine.CallFrameInfo> frames;final FlowEngine.CallFrameSnapshot frame;final boolean fallback;final List<Row> rows;
 FlowVariableInspection(FlowEngine.Runner runner,long requested){this(runner,requested,null);}
 FlowVariableInspection(FlowEngine.Runner runner,long requested,FlowVariableInspection previous){comparisonStep=previous==null?-1:previous.steps;Map<String,Row> old=new LinkedHashMap<>();if(previous!=null)for(Row row:previous.rows)old.put(row.name.toLowerCase(Locale.ROOT),row);if(runner==null)throw new IllegalArgumentException("Programma non disponibile.");generation=runner.generation();steps=runner.steps;state=runner.state;frames=runner.frameInfos();FlowEngine.CallFrameSnapshot chosen=runner.inspectFrame(requested);fallback=requested!=0&&chosen==null;if(fallback)chosen=runner.inspectFrame(0);frame=chosen;List<Row> sorted=new ArrayList<>();if(frame!=null)for(Map.Entry<String,FlowEngine.Value> pair:frame.variables.entrySet())sorted.add(new Row(frame,pair.getKey(),pair.getValue(),old.get(pair.getKey().toLowerCase(Locale.ROOT)),previous!=null));sorted.sort((a,b)->a.group!=b.group?Integer.compare(a.group,b.group):String.CASE_INSENSITIVE_ORDER.compare(a.name,b.name));rows=Collections.unmodifiableList(sorted);}
 Page<Row> filter(String query,int offset){query=query==null?"":query.trim();List<Row> all=new ArrayList<>();for(Row row:rows)if(contains(row.name,query))all.add(row);int start=pageStart(offset,all.size());return new Page<>(all.subList(start,Math.min(all.size(),start+PAGE_SIZE)),start,all.size());}
 Row find(String name){if(name==null)return null;for(Row row:rows)if(row.name.toLowerCase(Locale.ROOT).equals(name.toLowerCase(Locale.ROOT)))return row;return null;}
 String exportText(){StringBuilder text=new StringBuilder("Frociart · variabili della prova\n");text.append(frame==null?"Nessuna chiamata attiva":frame.functionName).append(" · passo ").append(steps).append('\n').append("Nome\tTipo\tRuolo\tValore\n");for(Row row:rows)text.append(row.name).append('\t').append(row.type).append('\t').append(row.role).append('\t').append(cell(row.value)).append('\n');return text.toString();}
 static String cell(FlowEngine.Value value){if(value.isVector()){StringBuilder b=new StringBuilder("[");for(int i=0;i<value.vectorSize();i++){if(i>0)b.append(", ");b.append(cell(value.element(i)));}return b.append(']').toString();}if(!value.isText())return value.format();String text=value.format();StringBuilder b=new StringBuilder("\"");for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='\\')b.append("\\\\");else if(c=='\"')b.append("\\\"");else if(c=='\n')b.append("\\n");else if(c=='\r')b.append("\\r");else if(c=='\t')b.append("\\t");else if(Character.isHighSurrogate(c)&&i+1<text.length()&&Character.isLowSurrogate(text.charAt(i+1))){b.append(c).append(text.charAt(++i));}else if(c<32||Character.isSurrogate(c))b.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else b.append(c);}return b.append('"').toString();}
 static boolean contains(String text,String query){for(int i=0;i<=text.length()-query.length();i++)if(text.regionMatches(true,i,query,0,query.length()))return true;return false;}
 static int pageStart(int requested,int total){if(total<0)throw new IllegalArgumentException("Conteggio non valido.");return total==0?0:Math.min(Math.max(0,requested)/PAGE_SIZE,(total-1)/PAGE_SIZE)*PAGE_SIZE;}
 static String compact(String value){if(value.isEmpty())return "(testo vuoto)";StringBuilder b=new StringBuilder();int i=0;while(i<value.length()){char c=value.charAt(i);String part=c=='\n'?"\\n":c=='\r'?"\\r":c=='\t'?"\\t":c=='\0'?"\\0":Character.isHighSurrogate(c)&&i+1<value.length()&&Character.isLowSurrogate(value.charAt(i+1))?value.substring(i,i+2):Character.isISOControl(c)||Character.isSurrogate(c)?String.format(Locale.ROOT,"\\u%04x",(int)c):String.valueOf(c);if(b.length()+part.length()>PREVIEW_LIMIT)break;b.append(part);i+=part.length()==2&&Character.isHighSurrogate(c)?2:1;}if(i<value.length())b.append('…');return b.toString();}
 static String comparisonCell(FlowEngine.Value value){if(value.isVector()){StringBuilder b=new StringBuilder("[");for(int i=0;i<value.vectorSize();i++){if(i>0)b.append(", ");b.append(comparisonCell(value.element(i)));}return b.append(']').toString();}if(value.isNumber()){String shown=value.format();return Double.parseDouble(shown)==value.asNumber()?shown:Double.toString(value.asNumber());}return cell(value);}
 static boolean same(FlowEngine.Value a,FlowEngine.Value b){if(a==b)return true;if(a==null||b==null)return false;if(a.isVector()||b.isVector()){if(!a.isVector()||!b.isVector()||a.vectorSize()!=b.vectorSize())return false;for(int i=0;i<a.vectorSize();i++)if(!same(a.element(i),b.element(i)))return false;return true;}if(a.isNumber()&&b.isNumber())return a.asNumber()==b.asNumber();if(a.isText()&&b.isText())return a.format().equals(b.format());return a.isBoolean()&&b.isBoolean()&&a.asBoolean()==b.asBoolean();}
 static final class Session {
  private static final class History {final FlowVariableInspection latest,previous;History(FlowVariableInspection latest,FlowVariableInspection previous){this.latest=latest;this.previous=previous;}}
  private final Map<Long,History> history=new LinkedHashMap<>();
  private FlowEngine.Runner runner;private long generation,frame,visit,requested;private int step;private boolean stable;private FlowEngine.State state;private FlowVariableInspection current;int captures;
  int trackedFrames(){return history.size();}
  FlowVariableInspection read(FlowEngine.Runner value,long selected){return read(value,selected,true);}
  FlowVariableInspection read(FlowEngine.Runner value,long selected,boolean paused){
   if(value==null){clear();return null;}
   if(current!=null&&runner==value&&generation==value.generation()&&frame==value.currentFrameId()&&visit==value.currentVisit()&&requested==selected&&step==value.steps&&state==value.state&&stable==paused)return current;
   if(runner!=value||generation!=value.generation())history.clear();
   Set<Long> active=new HashSet<>();for(FlowEngine.CallFrameInfo f:value.frameInfos())active.add(f.frameId);history.keySet().retainAll(active);
   long chosen=selected!=0&&active.contains(selected)?selected:value.currentFrameId();History prior=history.get(chosen);FlowVariableInspection baseline=!paused||prior==null?null:value.steps==prior.latest.steps?prior.previous:prior.latest;
   runner=value;generation=value.generation();frame=value.currentFrameId();visit=value.currentVisit();requested=selected;step=value.steps;state=value.state;stable=paused;captures++;
   current=new FlowVariableInspection(value,selected,baseline);if(paused&&current.frame!=null)history.put(current.frame.frameId,new History(current,baseline));return current;
  }
  Session copy(){Session result=new Session();result.restore(this);return result;}
  void restore(Session other){if(this==other)return;clear();if(other==null)return;runner=other.runner;generation=other.generation;frame=other.frame;visit=other.visit;requested=other.requested;step=other.step;state=other.state;stable=other.stable;current=other.current;captures=other.captures;for(Map.Entry<Long,History> entry:other.history.entrySet())history.put(entry.getKey(),new History(entry.getValue().latest,entry.getValue().previous));}
  void clear(){runner=null;current=null;history.clear();}
 }
}
